source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    groups = {3: [], 1: []}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and grid[p[0]][p[1]] == 2 and p not in seen:
                        seen.add(p)
                        stack.append(p)
            row_counts = {}
            for y, x in cells:
                row_counts[y] = row_counts.get(y, 0) + 1
            bar = [y for y, n in row_counts.items() if n >= 3]
            stem = [y for y, n in row_counts.items() if n == 1]
            if bar and stem:
                color = 3 if min(stem) < min(bar) else 1
            else:
                color = 3
            groups[color].append((sum(y for y, x in cells) / len(cells),
                                  sum(x for y, x in cells) / len(cells)))
    out = [[0] * 6 for _ in range(3)]
    for color, base in ((3, 0), (1, 3)):
        objs = sorted(groups[color])
        top_n = (len(objs) + 1) // 2
        rows = (objs[:top_n], objs[top_n:])
        for oi, row_objs in enumerate(rows):
            row_objs = sorted(row_objs, key=lambda p: p[1])
            for j, (cy, cx) in enumerate(row_objs):
                if j < 2:
                    out[2 * oi][base + 2 * j] = color
    return out
'''
